CREATE TABLE users (id BIGSERIAL PRIMARY KEY, email VARCHAR(180) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, name VARCHAR(120) NOT NULL, role VARCHAR(20) NOT NULL CHECK (role IN ('ADMIN','ANALYST','RESPONDER','VIEWER')), enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE incidents (id BIGSERIAL PRIMARY KEY, title VARCHAR(180) NOT NULL, type VARCHAR(40) NOT NULL, location VARCHAR(200) NOT NULL, description VARCHAR(2000), seed_risk DOUBLE PRECISION NOT NULL CHECK (seed_risk BETWEEN 0 AND 100), status VARCHAR(24) NOT NULL CHECK (status IN ('OPEN','IN_PROGRESS','RESOLVED','CLOSED')), created_by BIGINT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX incidents_status_idx ON incidents(status); CREATE INDEX incidents_created_at_idx ON incidents(created_at DESC);
CREATE TABLE risk_analyses (id BIGSERIAL PRIMARY KEY, incident_id BIGINT NOT NULL REFERENCES incidents(id), score DOUBLE PRECISION NOT NULL CHECK (score BETWEEN 0 AND 100), severity VARCHAR(20) NOT NULL CHECK (severity IN ('LOW','MEDIUM','HIGH','CRITICAL')), node_probabilities TEXT NOT NULL, local_factors TEXT NOT NULL, analyzed_by BIGINT NOT NULL REFERENCES users(id), analyzed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX risk_incident_analyzed_idx ON risk_analyses(incident_id, analyzed_at DESC);
CREATE TABLE alerts (id BIGSERIAL PRIMARY KEY, incident_id BIGINT NOT NULL REFERENCES incidents(id), severity VARCHAR(24) NOT NULL, message VARCHAR(500) NOT NULL, status VARCHAR(24) NOT NULL CHECK (status IN ('ACTIVE','ACKNOWLEDGED','RESOLVED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE recommendations (id BIGSERIAL PRIMARY KEY, incident_id BIGINT NOT NULL REFERENCES incidents(id), text VARCHAR(1200) NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'OPEN', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE simulations (id BIGSERIAL PRIMARY KEY, incident_id BIGINT NOT NULL REFERENCES incidents(id), created_by BIGINT NOT NULL REFERENCES users(id), inputs TEXT NOT NULL, score DOUBLE PRECISION NOT NULL CHECK (score BETWEEN 0 AND 100), severity VARCHAR(20) NOT NULL, node_probabilities TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id BIGSERIAL PRIMARY KEY, actor_id BIGINT NOT NULL REFERENCES users(id), action VARCHAR(80) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id VARCHAR(80), details TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
